#!/usr/bin/env node
// tools/bundle-css.js — flatten src/styles/main.css's @import chain into
// a single stylesheet.
//
// Why: main.css pulled in ~28 component stylesheets via @import, so the
// browser had to download main.css, parse it, then serially request every
// child — a waterfall that delays first paint most on slow connections
// (GitHub Pages adds ~100–300 ms RTT per hop from a cold cache). One
// bundled file removes all of those round trips while keeping the
// authoring workflow unchanged: styles stay split into readable files;
// this script concatenates them in import order, preserving cascade
// semantics exactly (imports are replaced in place, media-qualified
// imports like `print.css print` become @media blocks).
//
// Usage: npm run build:css   (writes src/styles/main.bundle.css)
// index.html references the bundle; main.css stays the source of truth
// for development (it still works standalone).

import fs from "node:fs";
import path from "node:path";

const ROOT = path.resolve(new URL(".", import.meta.url).pathname, "..");
const ENTRY = path.join(ROOT, "src/styles/main.css");
const OUT = path.join(ROOT, "src/styles/main.bundle.css");

/** Resolve one @import (optionally media-qualified) to CSS text. */
function resolveImport(importLine, fromDir) {
  const match = importLine.match(/^@import\s+(?:url\()?["']?([^"')]+)["']?\)?(?:\s+([^;]+))?;/);
  if (!match) {
    throw new Error(`Unrecognized @import: ${importLine}`);
  }
  const [, rel, media = null] = match;
  const file = path.resolve(fromDir, rel);
  const css = fs.readFileSync(file, "utf8");
  if (media) {
    // Media-qualified import ≡ wrapping the file in that @media block.
    return `/* ${rel} (${media}) — inlined by bundle-css */\n@media ${media} {\n${css}\n}`;
  }
  return `/* ${rel} — inlined by bundle-css */\n${css}`;
}

function bundle(entryFile) {
  const dir = path.dirname(entryFile);
  const src = fs.readFileSync(entryFile, "utf8");
  const lines = src.split("\n");
  const out = [];
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith("@import")) {
      out.push(resolveImport(trimmed, dir));
    } else {
      out.push(line);
    }
  }
  return out.join("\n");
}

const css = bundle(ENTRY);
fs.writeFileSync(OUT, `/* GENERATED by tools/bundle-css.js — do not edit by hand.\n   Edit src/styles/main.css (and the files it imports), then run:\n     npm run build:css\n   Why this exists: a single stylesheet removes the @import request\n   waterfall the 28-file chain caused. Cascade order below is exactly\n   main.css's import order. */\n\n${css}`);
console.log(`bundle-css: wrote ${path.relative(ROOT, OUT)} (${(css.length / 1024).toFixed(1)} KB)`);
